INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 17, 'theory', 'Load Balancing, CDN, and Reverse Proxy');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 0, 'How does an L7 balancer differ from an L4 one?', '["L7 parses HTTP and can route by host, path, and headers", "L7 is faster and does not parse requests", "L7 works only with UDP", "There is no difference"]', 0, 'L4 sees only addresses and ports; L7 understands the request but needs more CPU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 1, 'What happens without health checks if one of three servers is down?', '["Nothing: the balancer removes the server by itself", "The server restarts", "About every third request goes to the broken server and ends in an error", "All requests go to the remaining servers without errors"]', 2, 'The balancer keeps sending requests round robin, including to the dead server.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 2, 'Which algorithm always sends a given client to the same server?', '["Round robin", "Hash of the client address", "Least connections", "Random choice"]', 1, 'Source hashing (session affinity) is useful but makes the load uneven.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 3, 'A reverse proxy cannot reach the backend. Which code does the client get?', '["401", "404", "301", "502 Bad Gateway"]', 3, '502 says the gateway got an error from the upstream server or no response at all.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 17, 4, 'Why are "stateless" servers more convenient for horizontal scaling?', '["They use no memory", "They use no network", "Any server serves any client: session data lives in an external store", "They do not need a balancer"]', 2, 'Then the pool can grow and shrink freely, and a server failure does not lose sessions.');
